class Solution {
public:
    ListNode* reverseList(ListNode* head) {
        ListNode* prev = nullptr;
        ListNode* cur = head;
        while (cur) {
            ListNode* nxt = cur->next; // store next node
            cur->next = prev;          // reverse link
            prev = cur;                // move prev forward
            cur = nxt;                 // move cur forward
        }
        return prev;
    }
};
